<?php
/** CORE-008 native lifecycle, rollback, erasure and upgrade. Builder: Shashi. */
if (!defined('ABSPATH') || strpos(DB_NAME,'idlm_test_')!==0) { exit(1); }
function idlm_review_fixture(bool $external=true): array {
    global $wpdb,$administrator_id;wp_set_current_user($administrator_id);update_option('idlm_max_active_leads_per_rep',0);IDLM_Settings::sync_routing_from_legacy();
    $a=idlm_lifecycle_fixture(array('phone'=>'91'.random_int(8000000000,8999999999)));$b=idlm_lifecycle_fixture(array('phone'=>'91'.random_int(7000000000,7999999999)));
    $data=array('first_name'=>'Synthetic held prospect','email'=>$wpdb->get_var("SELECT email FROM {$wpdb->prefix}idlm_leads WHERE id={$a}"),'phone'=>$wpdb->get_var("SELECT phone FROM {$wpdb->prefix}idlm_leads WHERE id={$b}"),'source'=>'Website','budget'=>'8 lakh','gclid'=>'synthetic-click','access_token'=>'synthetic-secret');
    if($external){$data['fb_lead_id']=wp_generate_uuid4();}
    $result=IDLM_DB::upsert_inbound_lead($data,'website',$data,array('route'=>true));idlm_integration_assert_true(is_array($result),IDLM_DB::get_last_validation_error());idlm_integration_assert_same(0,$result['lead_id']);
    return array((int)$result['review_id'],$a,$b,$data);
}
function idlm_review_row(int $id) {
    global $wpdb;return $wpdb->get_row($wpdb->prepare("SELECT * FROM {$wpdb->prefix}idlm_inbound_submission_reviews WHERE id=%d",$id));
}
function idlm_review_digest(): string {
    global $wpdb;$all=array();foreach($wpdb->get_col("SHOW TABLES LIKE 'wp_idlm_%'")as$table){$all[$table]=$wpdb->get_results("SELECT * FROM {$table} ORDER BY 1",ARRAY_A);idlm_integration_assert_same('',$wpdb->last_error);}return hash('sha256',wp_json_encode($all));
}
idlm_integration_test('T02-N-CORE008-pending-external-replay-retains-one-review-no-lead-task-or-rerouting',static function():void {
    global $wpdb;[$id,$a,$b,$data]=idlm_review_fixture();$before=idlm_review_digest();$r=IDLM_DB::upsert_inbound_lead($data,'website',$data,array('route'=>true));idlm_integration_assert_same($id,$r['review_id']);idlm_integration_assert_same($before,idlm_review_digest());$row=idlm_review_row($id);idlm_integration_assert_same('Synthetic held prospect',json_decode($row->submission_data,true)['first_name']);idlm_integration_assert_true(strpos($row->submission_data,'synthetic-secret')===false);
});
foreach(array('matched','separate','rejected') as $decision){
    idlm_integration_test('T02-N-CORE008-'.$decision.'-is-audited-once-and-external-replay-obeys-decision',static function()use($decision):void {
        global $wpdb,$administrator_id;[$id,$a,$b,$data]=idlm_review_fixture();$lead_before=idlm_lifecycle_snapshot($a);$count=(int)$wpdb->get_var("SELECT COUNT(*) FROM {$wpdb->prefix}idlm_leads");
        $r=IDLM_Lead_Lifecycle_Service::resolve_inbound_review($id,$decision,$a,'Synthetic verified identity decision');idlm_integration_assert_true(!is_wp_error($r));$row=idlm_review_row($id);idlm_integration_assert_same($decision,$row->status);idlm_integration_assert_same($administrator_id,(int)$row->resolved_by);idlm_integration_assert_true(!empty($row->resolved_at));idlm_integration_assert_same('Synthetic verified identity decision',$row->resolution_note);
        idlm_integration_assert_same($count+($decision==='separate'?1:0),(int)$wpdb->get_var("SELECT COUNT(*) FROM {$wpdb->prefix}idlm_leads"));
        if($decision!=='rejected'){$lead=$wpdb->get_row("SELECT * FROM {$wpdb->prefix}idlm_leads WHERE id=".$r['lead_id']);idlm_integration_assert_same('New',$lead->stage);idlm_integration_assert_same(0,(int)$lead->assigned_rep_id);idlm_integration_assert_same(0,(int)$wpdb->get_var("SELECT COUNT(*) FROM {$wpdb->prefix}idlm_tasks WHERE lead_id=".$r['lead_id']));idlm_integration_assert_same(1,(int)$wpdb->get_var("SELECT COUNT(*) FROM {$wpdb->prefix}idlm_lead_touchpoints WHERE lead_id=".$r['lead_id']));if($decision==='separate'){idlm_integration_assert_same('Synthetic held prospect',$lead->first_name);idlm_integration_assert_same(0,(int)$lead->is_duplicate);}else{idlm_integration_assert_same($lead_before['idlm_leads'][0]['phone'],$lead->phone);}}
        $before=idlm_review_digest();idlm_integration_assert_true(is_wp_error(IDLM_Lead_Lifecycle_Service::resolve_inbound_review($id,'separate',0,'Repeat forbidden')));idlm_integration_assert_same($before,idlm_review_digest());$replay=IDLM_DB::upsert_inbound_lead($data,'website');idlm_integration_assert_same((int)$r['lead_id'],(int)$replay['lead_id']);idlm_integration_assert_same($before,idlm_review_digest());
    });
}
idlm_integration_test('T02-N-CORE008-invalid-missing-foreign-and-duplicate-candidates-and-blank-reasons-leave-state-unchanged',static function():void {
    global $wpdb;[$id,$a,$b]=idlm_review_fixture();$foreign=idlm_lifecycle_fixture();$before=idlm_review_digest();foreach(array(array('matched',$foreign,'Reason'),array('other',0,'Reason'),array('separate',0,''),array('rejected',0,str_repeat('x',1001)))as[$d,$target,$note]){idlm_integration_assert_true(is_wp_error(IDLM_Lead_Lifecycle_Service::resolve_inbound_review($id,$d,$target,$note)));idlm_integration_assert_same($before,idlm_review_digest());}
    $wpdb->update($wpdb->prefix.'idlm_leads',array('is_duplicate'=>1,'duplicate_of_id'=>$b),array('id'=>$a));$before=idlm_review_digest();idlm_integration_assert_true(is_wp_error(IDLM_Lead_Lifecycle_Service::resolve_inbound_review($id,'matched',$a,'Invalid duplicate')));idlm_integration_assert_same($before,idlm_review_digest());$wpdb->delete($wpdb->prefix.'idlm_leads',array('id'=>$a));idlm_integration_assert_true(is_wp_error(IDLM_Lead_Lifecycle_Service::resolve_inbound_review($id,'matched',$a,'Missing candidate')));
});
foreach(array('idlm_leads'=>'INSERT','idlm_lead_touchpoints'=>'INSERT','idlm_lead_activity_log'=>'INSERT','idlm_inbound_submission_reviews'=>'UPDATE','idlm_lead_outbox'=>'INSERT')as$table=>$operation){
    idlm_integration_test('T02-N-CORE008-required-'.$table.'-failure-rolls-back-separate-resolution-and-retries-once',static function()use($table,$operation):void {
        [$id]=idlm_review_fixture();$before=idlm_review_digest();$r=idlm_lifecycle_failure($table,$operation,static function()use($id){return IDLM_Lead_Lifecycle_Service::resolve_inbound_review($id,'separate',0,'Synthetic reason');});idlm_integration_assert_true(is_wp_error($r));idlm_integration_assert_same($before,idlm_review_digest());idlm_integration_assert_true(!is_wp_error(IDLM_Lead_Lifecycle_Service::resolve_inbound_review($id,'separate',0,'Synthetic retry')));
    });
}
idlm_integration_test('T02-N-CORE008-commit-denial-rolls-back-decision-and-contact-work',static function():void {
    [$id,$a]=idlm_review_fixture();$before=idlm_review_digest();$r=idlm_schema_filter(static function($sql){return $sql==='COMMIT'?'SELECT * FROM idlm_missing_review_commit':$sql;},static function()use($id,$a){return IDLM_Lead_Lifecycle_Service::resolve_inbound_review($id,'matched',$a,'Synthetic reason');});idlm_integration_assert_true(is_wp_error($r));idlm_integration_assert_same($before,idlm_review_digest());
});
idlm_integration_test('T16-N-CORE008-lead-erasure-removes-candidate-resolved-contact-and-malformed-reviews-but-keeps-unrelated',static function():void {
    global $wpdb;[$id,$a,$b]=idlm_review_fixture();[$other]=idlm_review_fixture();$wpdb->insert($wpdb->prefix.'idlm_inbound_submission_reviews',array('email'=>$wpdb->get_var("SELECT email FROM {$wpdb->prefix}idlm_leads WHERE id={$a}"),'candidate_lead_ids'=>'[]','status'=>'pending'));$contact=(int)$wpdb->insert_id;
    $r=IDLM_Lead_Lifecycle_Service::resolve_inbound_review($id,'separate',0,'Synthetic erasure test');$target=(int)$r['lead_id'];idlm_integration_assert_same(1,IDLM_Lead_Deletion_Service::delete($target));idlm_integration_assert_same(null,idlm_review_row($id));idlm_integration_assert_same(1,IDLM_Lead_Deletion_Service::delete($a));idlm_integration_assert_same(null,idlm_review_row($contact));idlm_integration_assert_true((bool)idlm_review_row($other));
    [$id,$a]=idlm_review_fixture();idlm_integration_assert_same(1,IDLM_Lead_Deletion_Service::delete($a));idlm_integration_assert_same(null,idlm_review_row($id));
});
idlm_integration_test('T16-N-CORE008-failed-review-erasure-rolls-back-lead-and-reviews',static function():void {
    [$id,$a]=idlm_review_fixture();$before=idlm_review_digest();$r=idlm_lifecycle_failure('idlm_inbound_submission_reviews','DELETE',static function()use($a){return IDLM_Lead_Deletion_Service::delete($a);});idlm_integration_assert_true(is_wp_error($r));idlm_integration_assert_same($before,idlm_review_digest());
