idlm_integration_test('T16-N-CORE008-reset-erases-independent-review-PII-inventory-and-delete-failure-rolls-back',static function():void {
    global $wpdb;idlm_review_fixture();$count=(string)$wpdb->get_var("SELECT COUNT(*) FROM {$wpdb->prefix}idlm_leads");$before=idlm_review_digest();$r=idlm_lifecycle_failure('idlm_inbound_submission_reviews','DELETE',static function()use($count){return IDLM_Lead_Deletion_Service::reset_all($count);});idlm_integration_assert_true(is_wp_error($r));idlm_integration_assert_same($before,idlm_review_digest());idlm_integration_assert_true(!is_wp_error(IDLM_Lead_Deletion_Service::reset_all($count)));idlm_integration_assert_same(0,(int)$wpdb->get_var("SELECT COUNT(*) FROM {$wpdb->prefix}idlm_inbound_submission_reviews"));
