idlm_integration_test('T16-N-CORE008-retention-is-bounded-checked-retryable-and-preserves-unexpired-review',static function():void {
    global $wpdb;[$keep]=idlm_review_fixture();for($i=0;$i<101;$i++){$wpdb->insert($wpdb->prefix.'idlm_inbound_submission_reviews',array('email'=>'expired@example.test','candidate_lead_ids'=>'[]','received_at'=>'2000-01-01 00:00:00','status'=>$i%2?'pending':'rejected'));}
    $before=idlm_review_digest();$r=idlm_lifecycle_failure('idlm_inbound_submission_reviews','DELETE',static function(){return IDLM_Identity_Review::prune();});idlm_integration_assert_true(is_wp_error($r));idlm_integration_assert_same($before,idlm_review_digest());idlm_integration_assert_same(100,IDLM_Identity_Review::prune());idlm_integration_assert_true((bool)wp_next_scheduled(IDLM_Identity_Review::PRUNE_HOOK));idlm_integration_assert_same(1,IDLM_Identity_Review::prune());idlm_integration_assert_true((bool)idlm_review_row($keep));
});
idlm_integration_test('T17-N-CORE008-additive-legacy-upgrade-and-complete-prior-backup-preserve-contact-evidence',static function():void {
    global $wpdb;idlm_native_backup_fixture();$table=$wpdb->prefix.'idlm_inbound_submission_reviews';$fields=array('submission_data','external_id','resolved_lead_id','resolved_by','resolved_at','resolution_note');
    $payload=idlm_native_backup_call('snapshot');$old=$payload;$old['schema']['core']='1.3.8';foreach($fields as$f){unset($old['schema']['columns']['idlm_inbound_submission_reviews'][$f]);foreach($old['tables']['idlm_inbound_submission_reviews']as&$row){unset($row[$f]);}unset($row);}
    idlm_integration_assert_same(true,idlm_native_backup_call('restore_payload',$old));$before=$wpdb->get_results("SELECT id,email,phone,candidate_lead_ids,payload,status FROM {$table}",ARRAY_A);
    idlm_integration_assert_true(false!==$wpdb->query("ALTER TABLE {$table} DROP INDEX platform_external, DROP INDEX resolved_lead"));foreach($fields as$f){idlm_integration_assert_true(false!==$wpdb->query("ALTER TABLE {$table} DROP COLUMN {$f}"));}update_option('idlm_schema_version','1.3.8');idlm_integration_assert_same(true,IDLM_DB::init());idlm_integration_assert_same(IDLM_DB_VERSION,get_option('idlm_schema_version'));idlm_integration_assert_same($before,$wpdb->get_results("SELECT id,email,phone,candidate_lead_ids,payload,status FROM {$table}",ARRAY_A));idlm_integration_assert_same(true,IDLM_DB::init());
});
idlm_integration_test('T02-C-CORE008-two-synchronized-manager-decisions-commit-only-one-separate-lead',static function():void {
    global $wpdb,$administrator_id;[$id]=idlm_review_fixture();$count=(int)$wpdb->get_var("SELECT COUNT(*) FROM {$wpdb->prefix}idlm_leads");$results=idlm_lifecycle_pair(array('review-race',$id,$administrator_id),array('review-race',$id,$administrator_id));$ok=0;foreach($results as$r){idlm_integration_assert_same(0,$r['status'],$r['stderr']);$ok+=($r['stdout']==='resolved');}idlm_integration_assert_same(1,$ok);idlm_integration_assert_same($count+1,(int)$wpdb->get_var("SELECT COUNT(*) FROM {$wpdb->prefix}idlm_leads"));
});
idlm_integration_test('T02-N-CORE008-lock-refusal-and-manager-revocation-during-wait-cannot-commit-decision',static function():void {
    global $wpdb,$administrator_id,$config;[$id,$a]=idlm_review_fixture();$before=idlm_review_digest();$r=idlm_schema_filter(static function($sql){return strpos($sql,'SELECT GET_LOCK(\'idlm_')===0&&strpos($sql,'idlm_rg_')===false?'SELECT 0':$sql;},static function()use($id,$a){return IDLM_Lead_Lifecycle_Service::resolve_inbound_review($id,'matched',$a,'Busy identity');});idlm_integration_assert_true(is_wp_error($r));idlm_integration_assert_same($before,idlm_review_digest());
    $manager=wp_insert_user(array('user_login'=>'review-manager-'.wp_generate_uuid4(),'user_pass'=>wp_generate_password(),'role'=>'subscriber'));$manager_user=get_userdata($manager);$manager_user->add_cap('idlm_access_leads');$manager_user->add_cap('idlm_assign_leads');wp_set_current_user($manager);$other=new wpdb($config['db_user'],$config['db_password'],$config['db_name'],$config['db_host']);$changed=false;
    try{$r=idlm_schema_filter(static function($sql)use($other,$manager,&$changed,$wpdb){if(!$changed&&strpos($sql,'SELECT * FROM '.$wpdb->prefix.'idlm_inbound_submission_reviews WHERE id = ')===0&&strpos($sql,'FOR UPDATE')!==false){$changed=true;$other->insert($wpdb->usermeta,array('user_id'=>$manager,'meta_key'=>'idlm_crm_access_disabled','meta_value'=>'1'));}return$sql;},static function()use($id,$a){return IDLM_Lead_Lifecycle_Service::resolve_inbound_review($id,'matched',$a,'Revoked actor');});idlm_integration_assert_true($changed, 'Live review lock was not reached by the authorized fixture manager.');idlm_integration_assert_true(is_wp_error($r));idlm_integration_assert_same($before,idlm_review_digest());}finally{$other->close();wp_set_current_user($administrator_id);}
});
idlm_integration_test('T16-N-CORE008-decisions-round-trip-and-all-complete-prior-inventories-normalize-without-current-omission',static function():void {
    global $wpdb;idlm_native_backup_fixture();foreach(array('matched','separate','rejected')as$d){[$id,$a]=idlm_review_fixture();idlm_integration_assert_true(!is_wp_error(IDLM_Lead_Lifecycle_Service::resolve_inbound_review($id,$d,$a,'Synthetic preserved decision')));}
    $payload=idlm_native_backup_call('snapshot');$before=$wpdb->get_results("SELECT * FROM {$wpdb->prefix}idlm_inbound_submission_reviews ORDER BY id",ARRAY_A);idlm_integration_assert_same(true,idlm_native_backup_call('restore_payload',$payload));idlm_integration_assert_same($before,$wpdb->get_results("SELECT * FROM {$wpdb->prefix}idlm_inbound_submission_reviews ORDER BY id",ARRAY_A));
    // Prior backups contained only pending reviews and no decision columns.
    $wpdb->query("DELETE FROM {$wpdb->prefix}idlm_inbound_submission_reviews WHERE status <> 'pending'");$pending=idlm_native_backup_call('snapshot');$fields=array('submission_data','external_id','resolved_lead_id','resolved_by','resolved_at','resolution_note');
    foreach(array('1.3.5','1.3.6','1.3.7','1.3.8')as$version){$old=$pending;$old['schema']['core']=$version;foreach($fields as$f){unset($old['schema']['columns']['idlm_inbound_submission_reviews'][$f]);foreach($old['tables']['idlm_inbound_submission_reviews']as&$row){unset($row[$f]);}unset($row);}if($version!=='1.3.8'){unset($old['schema']['columns']['idlm_tasks']['qualification_cycle']);foreach($old['tables']['idlm_tasks']as&$row){unset($row['qualification_cycle']);}unset($row);}idlm_integration_assert_same(true,idlm_native_backup_call('restore_payload',$old));}
    $bad=$pending;unset($bad['schema']['columns']['idlm_inbound_submission_reviews']['resolved_at']);$before=idlm_native_backup_digest();idlm_integration_assert_true(is_wp_error(idlm_native_backup_call('restore_payload',$bad)));idlm_integration_assert_same($before,idlm_native_backup_digest());
});
